-- Catalog review 8 Sep 2026. SAFE TO RE-RUN.
-- Patches meal ing/time/recipe from doc/MEAL-INGREDIENTS-REVIEW.md
-- and links the three new catalog keys to ingredient_prices.

update public.ingredient_prices
set meal_key = 'chopped tomatoes'
where slug = 'chopped-tomatoes';

update public.ingredient_prices
