  meal_key     = excluded.meal_key,
  product_name = excluded.product_name,
  pack_size    = excluded.pack_size,
  price_gbp    = excluded.price_gbp,
  unit_price   = excluded.unit_price,
  is_estimate  = excluded.is_estimate,
  captured_on  = excluded.captured_on;

update public.meals set time = 30, ing = '["black pepper", "feta", "garlic", "mixed herbs", "olive oil", "salt", "spaghetti", "spinach", "tomatoes"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 200°C (180°C fan). Halve 300g tomatoes (cherry or small tomatoes work best) and put them in a small baking dish with a 200g block of feta in the middle.", "Add 3 whole peeled garlic cloves, drizzle with 3 tbsp olive oil and season with 1 tsp mixed herbs, black pepper and a small pinch of salt (feta is already salty).", "Roast for 25 minutes until the feta is soft and the tomatoes have burst.", "Meanwhile, cook 180g spaghetti in salted boiling water for 9–10 minutes. Scoop out a mug of pasta water before draining.", "Take the dish out, mash the soft garlic into the feta with a fork and stir the feta and tomatoes into a creamy sauce.", "Add the drained spaghetti and 150g spinach to the dish and toss until the spinach wilts, adding splashes of pasta water until the sauce coats the pasta.", "Taste, adjust with black pepper, and serve straight away."], "tip": "Stir the feta and burst tomatoes together properly — that mash is what makes the sauce creamy."}$r$::jsonb where name = 'Baked feta pasta';
update public.meals set time = 25, ing = '["bell peppers", "black pepper", "chilli flakes", "cumin", "fresh coriander", "garlic", "lemons", "minced beef", "olive oil", "onions", "paprika", "salt", "tortillas", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Dice 1 onion and 2 bell peppers into small pieces and finely chop 2 garlic cloves.", "Heat 1 tbsp olive oil in a large frying pan over high heat. Add 300g minced beef and cook for 5 minutes, breaking it up, until browned.", "Add the onion and peppers and cook for 4 minutes until softened.", "Stir in the garlic, 1 tsp cumin, 1 tsp paprika, ½ tsp chilli flakes, ½ tsp salt and ¼ tsp black pepper. Cook for 1 minute until fragrant, then squeeze in the juice of half a lemon.", "Mix 4 tbsp yoghurt with the juice of the other lemon half and a pinch of salt.", "Warm 4 tortillas in a dry pan for 20–30 seconds per side.", "Fill the tortillas with the beef, top with the lemon yoghurt and a handful of roughly chopped fresh coriander, and serve."], "tip": "Let the beef sit in the pan without stirring for a minute at a time — the browned crust is where the flavour is."}$r$::jsonb where name = 'Beef & bell pepper tacos';
update public.meals set time = 25, ing = '["black pepper", "broccoli", "eggs", "garlic", "minced beef", "olive oil", "onions", "rice", "salt", "soy sauce"]'::jsonb, recipe = $r${"steps": ["If you have no cold leftover rice, cook 150g rice, spread it on a plate and let it steam off for 10 minutes so it fries rather than steams.", "Cut 1 head of broccoli into small florets, dice 1 onion and finely chop 3 garlic cloves.", "Heat 1 tbsp olive oil in a wok or large frying pan over high heat. Cook 300g minced beef for 5 minutes until browned, then tip onto a plate.", "Add another 1 tbsp olive oil, then the onion and broccoli. Stir-fry for 4 minutes, then add the garlic for 1 minute more.", "Push everything to one side, crack in 2 eggs and scramble them for 1 minute, then mix through.", "Return the beef and add the rice. Stir-fry for 3 minutes, breaking up clumps.", "Add 3 tbsp soy sauce and plenty of black pepper, toss for 1 minute, taste (soy sauce is salty, so add salt only if needed) and serve."], "tip": "Cold rice is the secret — warm, fresh rice turns mushy in the wok."}$r$::jsonb where name = 'Beef & broccoli fried rice';
update public.meals set time = 30, ing = '["black pepper", "chilli flakes", "chopped tomatoes", "cumin", "curry paste", "fresh coriander", "garlic", "minced beef", "olive oil", "onions", "paprika", "rice", "salt", "stock cubes", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Rinse 150g rice and cook in 300ml water with a pinch of salt: bring to the boil, cover, simmer on the lowest heat for 12 minutes, then leave covered off the heat.", "Finely dice 1 onion and chop 3 garlic cloves. Heat 1 tbsp olive oil in a large pan over medium-high heat and cook the onion for 4 minutes until soft.", "Add 400g minced beef and cook for 5–6 minutes, breaking it up, until browned.", "Stir in the garlic, 2 tbsp curry paste, 1 tsp cumin, 1 tsp paprika and ½ tsp chilli flakes. Cook for 1 minute.", "Add a 400g tin of chopped tomatoes, 1 crumbled stock cube and 100ml water. Simmer for 10 minutes until thick.", "Take off the heat and stir in 3 tbsp yoghurt. Season with salt and black pepper.", "Serve over the rice with a handful of chopped fresh coriander on top."], "tip": "Stir the yoghurt in off the heat so it stays creamy instead of splitting."}$r$::jsonb where name = 'Beef keema with rice';
update public.meals set time = 35, ing = '["black pepper", "eggs", "garlic", "minced beef", "mixed herbs", "olive oil", "onions", "parmesan", "passata", "salt", "spaghetti"]'::jsonb, recipe = $r${"steps": ["In a bowl, mix 400g minced beef with 1 egg, 2 finely chopped garlic cloves, 30g grated parmesan, 1 tsp mixed herbs, ½ tsp salt and ¼ tsp black pepper. Mix gently until just combined.", "Roll into 12 meatballs and chill while you start the sauce.", "Finely dice 1 onion and chop 1 garlic clove. Heat 1 tbsp olive oil in a large pan over medium heat and cook the onion for 4 minutes until soft, then add the garlic for 1 minute.", "Pour in 400g passata, add 1 tsp mixed herbs, a pinch of salt and black pepper, and simmer for 3 minutes.", "Heat 1 tbsp olive oil in a frying pan over medium-high heat and brown the meatballs for 5 minutes, turning, then nestle them into the sauce. Cover and simmer for 12 minutes until cooked through.", "Meanwhile, cook 180g spaghetti in salted boiling water for 9–10 minutes and drain.", "Serve the spaghetti topped with meatballs and sauce, extra grated parmesan and black pepper."], "tip": "Don't overwork the meatball mix — handle it lightly for tender meatballs."}$r$::jsonb where name = 'Beef meatballs in tomato sauce';
update public.meals set time = 35, ing = '["black pepper", "garlic", "minced beef", "mixed herbs", "olive oil", "onions", "parmesan", "passata", "salt", "spaghetti"]'::jsonb, recipe = $r${"steps": ["Finely dice 1 onion and chop 2 garlic cloves. Heat 1 tbsp olive oil in a large pan over medium heat and cook the onion for 5 minutes until soft.", "Turn the heat up, add 400g minced beef and cook for 6 minutes, breaking it up, until well browned.", "Stir in the garlic and 1 tsp mixed herbs for 1 minute.", "Pour in 400g passata and 100ml water, season with ½ tsp salt and ¼ tsp black pepper.", "Simmer on low, uncovered, for 20 minutes, stirring now and then, until thick and rich.", "Cook 180g spaghetti in salted boiling water for 9–10 minutes. Keep a mug of pasta water, then drain.", "Toss the spaghetti through the ragù, loosening with a splash of pasta water, and serve with 30g grated parmesan."], "tip": "The longer, slower simmer is what turns mince and passata into a proper ragù — don't rush step 5."}$r$::jsonb where name = 'Beef ragù spaghetti';
update public.meals set time = 40, ing = '["bell peppers", "black pepper", "garlic", "minced beef", "mixed herbs", "olive oil", "onions", "parmesan", "passata", "rice", "salt"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 200°C (180°C fan). Cook 100g rice in salted water for 12 minutes, then drain.", "Halve 3 bell peppers lengthways and remove the seeds. Place cut-side up in a baking dish, rub with 1 tbsp olive oil and season.", "Finely dice 1 onion and chop 2 garlic cloves. Heat 1 tbsp olive oil in a frying pan over medium-high heat and cook 300g minced beef for 5 minutes until browned.", "Add the onion and garlic and cook for 3 minutes, then stir in 1 tsp mixed herbs, ½ tsp salt, ¼ tsp black pepper, the cooked rice and 200g passata.", "Pack the filling into the pepper halves. Pour the remaining 200g passata around them and sprinkle 30g grated parmesan over the tops.", "Bake for 25 minutes until the peppers are tender and the tops are golden.", "Rest for 3 minutes and serve with the sauce from the dish spooned over."], "tip": "Pack the filling firmly so the halves hold together when you lift them out."}$r$::jsonb where name = 'Beef stuffed peppers';
update public.meals set time = 30, ing = '["black pepper", "broccoli", "chicken thighs", "garlic", "lemons", "olive oil", "paprika", "rice", "salt", "soy sauce"]'::jsonb, recipe = $r${"steps": ["Rinse 150g rice and cook in 300ml water: bring to the boil, cover, simmer on the lowest heat for 12 minutes, then rest covered.", "Cut 4 boneless chicken thighs into bite-sized pieces and toss with 1 tsp paprika, ½ tsp salt and ¼ tsp black pepper.", "Heat 1 tbsp olive oil in a large frying pan over medium-high heat. Cook the chicken for 8 minutes, turning, until golden and cooked through. Set aside.", "Cut 1 head of broccoli into small florets and chop 3 garlic cloves. Add 1 tbsp olive oil to the pan, then the broccoli and 3 tbsp water. Cover and cook for 4 minutes.", "Uncover, add the garlic and cook for 1 minute, then return the chicken with 2 tbsp soy sauce and the juice of 1 lemon. Toss for 1 minute.", "Divide the rice between bowls, top with the chicken and broccoli and spoon over the pan juices."], "tip": "Steaming the broccoli briefly under a lid keeps it bright and tender-crisp."}$r$::jsonb where name = 'Chicken & broccoli rice bowls';
update public.meals set time = 30, ing = '["black pepper", "chicken thighs", "chickpeas", "chilli flakes", "coconut milk", "cumin", "curry paste", "fresh coriander", "garlic", "olive oil", "onions", "paprika", "rice", "salt", "spinach", "stock cubes"]'::jsonb, recipe = $r${"steps": ["Rinse 150g rice and cook in 300ml water with a pinch of salt: boil, cover, simmer on the lowest heat for 12 minutes, then rest covered.", "Dice 1 onion and chop 3 garlic cloves. Heat 1 tbsp olive oil in a large pan over medium-high heat and cook the onion for 4 minutes.", "Cut 4 boneless chicken thighs into chunks, add to the pan and cook for 5 minutes until lightly browned.", "Stir in the garlic, 2 tbsp curry paste, 1 tsp cumin, 1 tsp paprika and ½ tsp chilli flakes. Cook for 1 minute.", "Add a 400ml tin of coconut milk, 1 crumbled stock cube and a drained 400g tin of chickpeas. Simmer for 12 minutes until the chicken is cooked through and the sauce has thickened.", "Stir in 150g spinach until wilted. Season with salt and black pepper.", "Serve over the rice, topped with chopped fresh coriander."], "tip": "Brown the chicken properly before the liquid goes in — it's where the depth of flavour comes from."}$r$::jsonb where name = 'Chicken & chickpea curry';
update public.meals set time = 30, ing = '["bell peppers", "black pepper", "chicken thighs", "chilli flakes", "cumin", "garlic", "olive oil", "onions", "paprika", "rice", "salt", "stock cubes", "tomatoes"]'::jsonb, recipe = $r${"steps": ["Cut 4 boneless chicken thighs into bite-sized pieces and toss with 1 tsp cumin, 1 tsp paprika, ½ tsp salt and ¼ tsp black pepper.", "Heat 1 tbsp olive oil in a large pan with a lid over medium-high heat. Cook the chicken for 6 minutes until golden, then set aside.", "Dice 1 onion and 2 bell peppers and chop 2 garlic cloves. Add 1 tbsp olive oil to the pan, cook the onion and peppers for 4 minutes, then the garlic and ½ tsp chilli flakes for 1 minute.", "Stir in 150g rice and toast for 1 minute. Add 350ml water with 1 crumbled stock cube and bring to the boil.", "Return the chicken, cover, and simmer on the lowest heat for 15 minutes until the rice is tender and the water absorbed.", "Dice 2 tomatoes, stir them through, and rest covered for 3 minutes.", "Taste, adjust salt and pepper, and serve."], "tip": "Toasting the rice in the spiced oil keeps the grains separate and adds a nutty depth."}$r$::jsonb where name = 'Chicken fajita rice';
update public.meals set time = 40, ing = '["black pepper", "chicken thighs", "garlic", "mixed herbs", "olive oil", "parmesan", "passata", "salt", "spaghetti"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 200°C (180°C fan). Pat 4 chicken thighs dry and season with ½ tsp salt, ¼ tsp black pepper and 1 tsp mixed herbs.", "Heat 1 tbsp olive oil in an ovenproof frying pan over medium-high heat. Brown the chicken skin-side down for 5 minutes, flip for 2 minutes, then set aside.", "Chop 2 garlic cloves and cook in the same pan for 30 seconds. Pour in 400g passata, add 1 tsp mixed herbs and a pinch of salt, and simmer for 2 minutes.", "Return the chicken skin-side up, sprinkle 40g grated parmesan over the thighs and bake for 22 minutes until cooked through and golden.", "Meanwhile, cook 160g spaghetti in salted boiling water for 9–10 minutes, drain and toss with 1 tsp olive oil.", "Serve the spaghetti topped with the chicken and sauce, with extra parmesan and black pepper."], "tip": "Browning the chicken first gives a golden crust and flavours the sauce."}$r$::jsonb where name = 'Chicken parm-style bake';
update public.meals set time = 35, ing = '["black pepper", "chicken thighs", "chilli flakes", "cumin", "curry paste", "garlic", "olive oil", "onions", "paprika", "rice", "salt", "spinach", "stock cubes", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Rinse 150g rice and cook in 300ml water with a pinch of salt: boil, cover, simmer on the lowest heat for 12 minutes, then rest covered.", "Cut 4 boneless chicken thighs into chunks and toss with 1 tsp paprika, ½ tsp salt and ¼ tsp black pepper.", "Heat 1 tbsp olive oil in a large pan over medium-high heat. Brown the chicken for 5 minutes, then set aside.", "Dice 1 onion and chop 3 garlic cloves. Add 1 tbsp olive oil, cook the onion for 5 minutes, then the garlic, 2 tbsp curry paste, 1 tsp cumin and ½ tsp chilli flakes for 1 minute.", "Add 200ml water and 1 crumbled stock cube, return the chicken, cover and simmer for 12 minutes until cooked through.", "Add 200g spinach in handfuls, stirring until wilted, about 3 minutes.", "Take off the heat and stir in 100g yoghurt. Season with salt and black pepper and serve over the rice."], "tip": "Add the yoghurt off the heat — boiling it makes it split."}$r$::jsonb where name = 'Chicken saag-style curry';
update public.meals set time = 25, ing = '["black pepper", "chicken thighs", "chilli flakes", "cumin", "curry paste", "fresh coriander", "garlic", "lemons", "olive oil", "onions", "paprika", "salt", "tomatoes", "tortillas", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Mix 100g yoghurt with 2 tbsp curry paste, 1 chopped garlic clove, 1 tsp cumin, 1 tsp paprika, ½ tsp chilli flakes, the juice of half a lemon, ½ tsp salt and ¼ tsp black pepper.", "Cut 4 boneless chicken thighs into chunks and coat in the marinade. Leave for 10 minutes (or up to overnight in the fridge).", "Thinly slice ½ onion and dice 2 tomatoes. Toss with the juice of the other lemon half and a pinch of salt.", "Heat 1 tbsp olive oil in a large frying pan over high heat. Cook the chicken for 10 minutes, turning, until charred at the edges and cooked through.", "Warm 4 tortillas in a dry pan for 30 seconds per side.", "Mix 100g yoghurt with a pinch of salt for the sauce.", "Fill the tortillas with chicken, the onion and tomato salad, a spoon of yoghurt and chopped fresh coriander. Roll and serve."], "tip": "Get the pan really hot so the marinade chars — that's the tikka flavour."}$r$::jsonb where name = 'Chicken tikka-style wraps';
update public.meals set time = 30, ing = '["black pepper", "chickpeas", "chilli flakes", "coconut milk", "cumin", "curry paste", "garlic", "olive oil", "onions", "paprika", "potatoes", "salt", "spinach", "stock cubes"]'::jsonb, recipe = $r${"steps": ["Dice 1 onion, chop 2 garlic cloves and cut 500g potatoes into 2cm chunks.", "Heat 1 tbsp olive oil in a large pot over medium heat and cook the onion for 4 minutes until soft, then the garlic for 1 minute.", "Stir in 2 tbsp curry paste, 1 tsp cumin, 1 tsp paprika and ¼ tsp chilli flakes. Cook for 1 minute.", "Add the potatoes, a 400ml tin of coconut milk, 300ml water and 1 crumbled stock cube. Bring to a simmer, cover and cook for 15 minutes until the potatoes are tender.", "Add a drained 400g tin of chickpeas and 150g spinach. Stir until the spinach wilts, about 2 minutes.", "Season with salt and black pepper and serve in bowls."], "tip": "Frying the curry paste with the onion before the liquid goes in wakes the spices up."}$r$::jsonb where name = 'Chickpea & potato coconut stew';
update public.meals set time = 25, ing = '["black pepper", "chickpeas", "chilli flakes", "chopped tomatoes", "coconut milk", "cumin", "curry paste", "fresh coriander", "garlic", "olive oil", "onions", "paprika", "rice", "salt", "spinach", "stock cubes"]'::jsonb, recipe = $r${"steps": ["Rinse 150g rice and cook in 300ml water with a pinch of salt: boil, cover, simmer on the lowest heat for 12 minutes, then rest covered.", "Dice 1 onion and chop 3 garlic cloves. Heat 1 tbsp olive oil in a large pan over medium heat and cook the onion for 4 minutes, then the garlic for 1 minute.", "Stir in 2 tbsp curry paste, 1 tsp cumin, 1 tsp paprika and ½ tsp chilli flakes for 1 minute.", "Add a 400g tin of chopped tomatoes, 200ml coconut milk (half a tin), 1 crumbled stock cube and a drained 400g tin of chickpeas. Simmer for 10 minutes until thickened.", "Stir in 150g spinach until wilted. Season with salt and black pepper.", "Serve over the rice, topped with chopped fresh coriander."], "tip": "Crush a few chickpeas against the side of the pan to thicken the sauce naturally."}$r$::jsonb where name = 'Chickpea & spinach curry';
update public.meals set time = 25, ing = '["bell peppers", "black pepper", "chickpeas", "cumin", "eggs", "garlic", "mixed herbs", "olive oil", "onions", "paprika", "passata", "salt", "tortillas"]'::jsonb, recipe = $r${"steps": ["Dice 1 onion and 1 bell pepper and chop 2 garlic cloves. Heat 1 tbsp olive oil in a large frying pan with a lid over medium heat.", "Cook the onion and pepper for 6 minutes until soft, then add the garlic for 1 minute.", "Stir in 1 tsp cumin, 1 tsp paprika, ½ tsp mixed herbs, ½ tsp salt and ¼ tsp black pepper. Cook for 30 seconds.", "Pour in 300g passata and a drained 400g tin of chickpeas. Simmer for 6 minutes until slightly thickened.", "Make 4 wells in the sauce and crack an egg into each. Cover and cook on low for 5–6 minutes until the whites are set and the yolks still soft.", "Warm 4 tortillas in a dry pan for 30 seconds per side. Serve the shakshuka from the pan with the tortillas for scooping."], "tip": "Cover the pan fully for firmer yolks, or leave it slightly open for runny ones."}$r$::jsonb where name = 'Chickpea shakshuka';
update public.meals set time = 30, ing = '["black pepper", "chilli flakes", "coconut milk", "cumin", "curry paste", "fresh coriander", "garlic", "lemons", "olive oil", "onions", "paprika", "rice", "salmon fillet", "salt", "spinach", "stock cubes"]'::jsonb, recipe = $r${"steps": ["Rinse 150g rice and cook in 300ml water with a pinch of salt: boil, cover, simmer on the lowest heat for 12 minutes, then rest covered.", "Dice 1 onion and chop 2 garlic cloves. Heat 1 tbsp olive oil in a large pan over medium heat and cook the onion for 4 minutes, then the garlic for 1 minute.", "Stir in 2 tbsp curry paste, 1 tsp cumin, ½ tsp paprika and ¼ tsp chilli flakes for 1 minute.", "Add a 400ml tin of coconut milk and 1 crumbled stock cube. Simmer for 5 minutes.", "Cut 2 salmon fillets into large chunks (skin removed) and add to the pan. Simmer gently for 5 minutes until just cooked.", "Stir in 150g spinach until wilted, then the juice of half a lemon. Season with salt and black pepper.", "Serve over the rice with chopped fresh coriander and lemon wedges."], "tip": "Simmer gently once the salmon is in — it's done as soon as it flakes."}$r$::jsonb where name = 'Coconut salmon curry';
update public.meals set time = 35, ing = '["black pepper", "broccoli", "butter", "lemons", "olive oil", "paprika", "potatoes", "salmon fillet", "salt", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 220°C (200°C fan). Cut 500g potatoes into 3cm chunks and boil in salted water for 15 minutes until tender.", "Drain, tip onto a baking tray, lightly crush each piece with a fork, and toss with 2 tbsp olive oil, ½ tsp paprika, salt and black pepper. Roast for 15 minutes until crisp.", "Cut 1 head of broccoli into florets, toss with 1 tbsp olive oil, salt and pepper, and add to the tray for the last 10 minutes.", "Pat 2 salmon fillets dry and season the skin with salt. Heat 1 tbsp olive oil in a frying pan over medium-high heat and cook skin-side down for 5 minutes without moving.", "Flip, add 15g butter and cook for 2 minutes, spooning the butter over, until just cooked through.", "Mix 4 tbsp yoghurt with the juice of half a lemon and a pinch of salt.", "Serve the salmon on the smashed potatoes and broccoli with the lemon yoghurt and lemon wedges."], "tip": "Dry skin plus a hot pan and no fiddling — that's the whole secret to crispy salmon skin."}$r$::jsonb where name = 'Crispy salmon & smashed potatoes';
update public.meals set time = 40, ing = '["black pepper", "chilli flakes", "chopped tomatoes", "cumin", "curry paste", "minced beef", "olive oil", "onions", "paprika", "potatoes", "salt", "stock cubes", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 200°C (180°C fan). Cut 500g potatoes into 2cm cubes and dice 1 onion.", "Heat 1 tbsp olive oil in a large ovenproof pan or roasting tin on the hob over medium-high heat. Brown 300g minced beef for 5 minutes, breaking it up.", "Add the onion and cook for 3 minutes, then stir in 2 tbsp curry paste, 1 tsp cumin, ½ tsp paprika and ¼ tsp chilli flakes for 1 minute.", "Add the potatoes, a 400g tin of chopped tomatoes, 1 crumbled stock cube and 150ml water. Season with ½ tsp salt and ¼ tsp black pepper and stir.", "Cover with foil and bake for 25 minutes, then uncover and bake 5 minutes more until the potatoes are tender.", "Serve in bowls with a spoonful of yoghurt on top."], "tip": "Keep the potato cubes small and even so they cook through in the time."}$r$::jsonb where name = 'Curried beef & potato traybake';
update public.meals set time = 20, ing = '["black pepper", "broccoli", "eggs", "garlic", "olive oil", "onions", "rice", "salt", "soy sauce"]'::jsonb, recipe = $r${"steps": ["Use 300g cold cooked rice (about 150g dry cooked earlier and cooled — fresh rice goes mushy).", "Cut 1 head of broccoli into small florets, dice 1 onion, chop 3 garlic cloves and beat 4 eggs.", "Heat 1 tbsp olive oil in a wok or large frying pan over high heat. Stir-fry the onion for 2 minutes, then the broccoli with 2 tbsp water for 4 minutes until tender-crisp.", "Add the garlic for 30 seconds, then push everything to one side.", "Add 1 tbsp olive oil and the eggs; scramble for 1 minute, then mix through.", "Add the rice and stir-fry for 3 minutes, breaking up clumps.", "Add 3 tbsp soy sauce and plenty of black pepper, toss for 1 minute, taste for salt and serve."], "tip": "Cook the rice in the morning or the day before and keep it in the fridge — cold rice is what makes fried rice work."}$r$::jsonb where name = 'Egg fried rice with broccoli';
update public.meals set time = 15, ing = '["bell peppers", "black pepper", "eggs", "feta", "olive oil", "paprika", "salt", "spinach", "tortillas"]'::jsonb, recipe = $r${"steps": ["Slice 2 bell peppers into thin strips. Heat 1 tbsp olive oil in a large frying pan over medium heat and cook the peppers for 5 minutes until soft, with a pinch of salt.", "Add 100g spinach and cook for 1 minute until wilted.", "Beat 4 eggs with ½ tsp paprika, a pinch of salt and black pepper.", "Turn the heat to low, pour the eggs over the peppers and stir gently for 3 minutes until just set.", "Crumble in 100g feta and fold through; take off the heat.", "Warm 4 tortillas in a dry pan for 30 seconds per side.", "Divide the filling between the tortillas, dust with paprika, roll up tightly and serve."], "tip": "Take the eggs off the heat while still slightly glossy — they finish cooking in the wrap."}$r$::jsonb where name = 'Feta & pepper egg wraps';
update public.meals set time = 30, ing = '["black pepper", "chicken thighs", "feta", "garlic", "lemons", "mixed herbs", "olive oil", "rice", "salt", "tomatoes", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Rinse 150g rice and cook in 300ml water with a pinch of salt: boil, cover, simmer on the lowest heat for 12 minutes, then rest covered.", "Cut 4 boneless chicken thighs into chunks and toss with 1 tbsp olive oil, 1 tsp mixed herbs, the zest of 1 lemon, 1 chopped garlic clove, ½ tsp salt and ¼ tsp black pepper.", "Heat 1 tbsp olive oil in a large frying pan over high heat. Cook the chicken for 10 minutes, turning, until charred and cooked through. Squeeze over half the lemon.", "Dice 3 tomatoes and toss with 1 tbsp olive oil, the remaining lemon juice, a pinch of salt and pepper.", "Mix 150g yoghurt with 1 finely grated garlic clove and a pinch of salt.", "Build the bowls: rice, chicken, tomato salad, a spoon of garlic yoghurt and 100g crumbled feta. Finish with black pepper."], "tip": "Charred edges on the chicken are the point — keep the pan hot and don't crowd it."}$r$::jsonb where name = 'Greek chicken bowls';
update public.meals set time = 15, ing = '["black pepper", "chickpeas", "feta", "lemons", "mixed herbs", "olive oil", "onions", "salt", "spinach", "tomatoes"]'::jsonb, recipe = $r${"steps": ["Drain and rinse a 400g tin of chickpeas and pat dry.", "Dice 3 tomatoes and very thinly slice ¼ onion.", "In a large bowl, whisk 3 tbsp olive oil with the juice of 1 lemon, 1 tsp mixed herbs, ¼ tsp salt and black pepper.", "Add the chickpeas, tomatoes and onion and toss. Leave for 5 minutes to soak up the dressing.", "Divide 100g spinach between two bowls and spoon the chickpea mix on top.", "Crumble over 100g feta, finish with a little more olive oil and black pepper, and serve."], "tip": "Let the chickpeas sit in the dressing for a few minutes — they soak up far more flavour than the leaves do."}$r$::jsonb where name = 'Greek-style chickpea salad bowls';
update public.meals set time = 25, ing = '["black pepper", "broccoli", "garlic", "halloumi", "lemons", "olive oil", "paprika", "rice", "salt"]'::jsonb, recipe = $r${"steps": ["Rinse 150g rice and cook in 300ml water with a pinch of salt: boil, cover, simmer on the lowest heat for 12 minutes, then rest covered.", "Cut 1 head of broccoli into small florets and chop 2 garlic cloves. Slice a 225g block of halloumi into 8 slices and pat dry.", "Heat 1 tbsp olive oil in a large frying pan over medium-high heat. Add the broccoli and 3 tbsp water, cover and cook for 4 minutes.", "Uncover, add the garlic, 1 tsp paprika, a pinch of salt and black pepper, and cook for 2 minutes until the edges catch. Tip into a bowl.", "Add 1 tbsp olive oil to the pan and fry the halloumi for 2 minutes per side until golden.", "Divide the rice between bowls, top with broccoli and halloumi, squeeze over the juice of 1 lemon and finish with black pepper."], "tip": "Leave the halloumi alone in the pan until it releases easily — that's when the crust has formed."}$r$::jsonb where name = 'Halloumi & broccoli grain bowls';
update public.meals set time = 30, ing = '["bell peppers", "black pepper", "chickpeas", "halloumi", "lemons", "olive oil", "onions", "paprika", "salt"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 220°C (200°C fan). Cut 1 onion into wedges and 2 bell peppers into chunks. Toss on a large tray with 2 tbsp olive oil, 1 tsp paprika, a pinch of salt and black pepper.", "Roast for 15 minutes until softening at the edges.", "Drain a 400g tin of chickpeas and cut a 225g block of halloumi into 1cm slices.", "Stir the chickpeas into the tray, lay the halloumi on top, drizzle with 1 tbsp olive oil and squeeze over half a lemon.", "Roast for 12 minutes more until the halloumi is golden.", "Finish with the juice of the other lemon half and black pepper, and serve."], "tip": "Spread everything in one layer — a crowded tray steams instead of roasting."}$r$::jsonb where name = 'Halloumi & chickpea traybake';
update public.meals set time = 20, ing = '["bell peppers", "black pepper", "chilli flakes", "cumin", "fresh coriander", "halloumi", "lemons", "olive oil", "onions", "paprika", "salt", "tortillas", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Slice a 225g block of halloumi into strips and pat dry. Slice 1 onion and 2 bell peppers into strips.", "Heat 1 tbsp olive oil in a large frying pan over medium-high heat. Fry the halloumi for 2 minutes per side until golden, then set aside.", "Add 1 tbsp olive oil, then the onion and peppers. Cook for 6 minutes until soft and charred in places.", "Sprinkle over 1 tsp cumin, 1 tsp paprika, ½ tsp chilli flakes, a pinch of salt and black pepper. Cook for 1 minute.", "Return the halloumi and squeeze over the juice of half a lemon.", "Mix 4 tbsp yoghurt with the remaining lemon juice and a pinch of salt. Warm 4 tortillas in a dry pan for 30 seconds per side.", "Fill the tortillas with halloumi and peppers, top with lemon yoghurt and chopped fresh coriander, and serve."], "tip": "Dry the halloumi well — wet halloumi steams and never browns."}$r$::jsonb where name = 'Halloumi fajitas';
update public.meals set time = 20, ing = '["black pepper", "halloumi", "lemons", "mixed herbs", "olive oil", "onions", "salt", "spinach", "tomatoes", "tortillas", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Slice a 225g block of halloumi into 8 slices and pat dry.", "Mix 150g yoghurt with 1 tsp mixed herbs, the juice of half a lemon, a pinch of salt and black pepper.", "Very thinly slice ¼ onion and dice 2 tomatoes. Toss with the remaining lemon juice and a pinch of salt.", "Heat 1 tbsp olive oil in a frying pan over medium-high heat and fry the halloumi for 2 minutes per side until golden.", "Warm 4 tortillas in a dry pan for 30 seconds per side.", "Spread each tortilla with herby yoghurt, add a handful of spinach, the halloumi, and the tomato and onion. Roll tightly and serve."], "tip": "Soaking the sliced onion in the lemon juice for a few minutes softens its bite."}$r$::jsonb where name = 'Halloumi wraps with herby yoghurt';
update public.meals set time = 35, ing = '["black pepper", "butter", "chicken thighs", "garlic", "lemons", "mixed herbs", "olive oil", "parmesan", "rice", "salt", "spinach"]'::jsonb, recipe = $r${"steps": ["Rinse 150g rice and cook in 300ml water with a pinch of salt: boil, cover, simmer on the lowest heat for 12 minutes, then rest covered.", "Pat 4 chicken thighs dry and season with 1 tsp mixed herbs, ½ tsp salt and ¼ tsp black pepper.", "Heat 1 tbsp olive oil in a large frying pan with a lid over medium-high heat. Cook the chicken skin-side down for 6 minutes until golden, then flip.", "Add 2 chopped garlic cloves, the juice of 1 lemon and 100ml water. Cover and simmer for 12 minutes until cooked through.", "Lift the chicken out. Add 150g spinach to the pan juices and stir for 2 minutes until wilted.", "Stir 15g butter and 40g grated parmesan into the hot rice with black pepper.", "Serve the rice topped with the chicken, spinach and pan juices, with lemon wedges."], "tip": "Stir the parmesan into the rice while it's still hot so it melts in rather than clumping."}$r$::jsonb where name = 'Lemon chicken & parmesan rice';
update public.meals set time = 45, ing = '["black pepper", "broccoli", "chicken thighs", "garlic", "lemons", "olive oil", "paprika", "potatoes", "salt"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 220°C (200°C fan). Cut 500g potatoes into 2cm chunks and toss on a large tray with 2 tbsp olive oil, 4 whole unpeeled garlic cloves, salt and black pepper.", "Pat 4 chicken thighs dry and rub with 1 tbsp olive oil, 1 tsp paprika, ½ tsp salt and ¼ tsp black pepper. Nestle skin-side up among the potatoes. Cut 1 lemon into wedges and add to the tray.", "Roast for 25 minutes.", "Cut 1 head of broccoli into florets and toss with 1 tbsp olive oil and a pinch of salt. Add to the tray and roast for 12 minutes more until the chicken is golden and cooked through and the potatoes are crisp.", "Squeeze the roasted lemon wedges and the soft garlic over everything and serve from the tray."], "tip": "Space the chicken and potatoes out — a packed tray steams and won't crisp."}$r$::jsonb where name = 'Lemon garlic roast chicken & potatoes';
update public.meals set time = 25, ing = '["black pepper", "broccoli", "garlic", "lemons", "mixed herbs", "olive oil", "parmesan", "salmon fillet", "salt", "spaghetti"]'::jsonb, recipe = $r${"steps": ["Bring a large pan of salted water to the boil and cook 180g spaghetti for 9–10 minutes. Cut 1 head of broccoli into small florets and drop them into the pasta water for the last 3 minutes. Keep a mug of pasta water, then drain.", "Meanwhile, season 2 salmon fillets with salt, black pepper and 1 tsp mixed herbs. Heat 1 tbsp olive oil in a large frying pan over medium-high heat and cook skin-side down for 5 minutes, then flip for 2 minutes. Lift out and flake into chunks, discarding the skin.", "Add 1 tbsp olive oil and 3 chopped garlic cloves to the pan and cook for 1 minute.", "Add the drained pasta and broccoli, the zest and juice of 1 lemon, 30g grated parmesan and a splash of pasta water. Toss until glossy.", "Fold in the salmon gently, season with salt and pepper, and serve with extra parmesan."], "tip": "Cooking the broccoli in the pasta water saves a pan and keeps it tender without going soggy."}$r$::jsonb where name = 'Salmon & broccoli pasta';
update public.meals set time = 20, ing = '["black pepper", "chilli flakes", "cumin", "fresh coriander", "lemons", "olive oil", "onions", "paprika", "salmon fillet", "salt", "spinach", "tortillas", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 200°C (180°C fan). Rub 2 salmon fillets with 1 tbsp olive oil, 1 tsp paprika, 1 tsp cumin, ¼ tsp chilli flakes, ½ tsp salt and black pepper. Bake for 12 minutes until it flakes.", "Mix 150g yoghurt with the zest and juice of 1 lemon and a pinch of salt.", "Very thinly slice ½ onion and toss with a squeeze of lemon and a pinch of salt.", "Warm 4 tortillas in a dry pan for 30 seconds per side.", "Flake the salmon into chunks, discarding the skin.", "Spread each tortilla with lemon yoghurt, add a small handful of spinach, the salmon, the onion and chopped fresh coriander. Serve with lemon wedges."], "tip": "The salmon is done the moment it flakes — take it out early rather than late."}$r$::jsonb where name = 'Salmon tacos with lemon yoghurt';
update public.meals set time = 30, ing = '["black pepper", "broccoli", "garlic", "lemons", "olive oil", "paprika", "potatoes", "salmon fillet", "salt"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 220°C (200°C fan). Cut 500g potatoes into 2cm cubes and toss on a large tray with 2 tbsp olive oil, ½ tsp paprika, salt and black pepper. Roast for 15 minutes.", "Cut 1 head of broccoli into florets, chop 2 garlic cloves and slice 1 lemon into thin rounds.", "Push the potatoes to the sides. Place 2 salmon fillets in the middle, season with salt, pepper and ½ tsp paprika, and top with the lemon slices.", "Scatter the broccoli and garlic around, drizzle with 1 tbsp olive oil and a pinch of salt.", "Roast for 13 minutes until the salmon flakes and the broccoli is tender. Serve straight from the tray."], "tip": "Cut the potatoes evenly at 2cm so they're done in the same time as the salmon."}$r$::jsonb where name = 'Salmon traybake';
update public.meals set time = 25, ing = '["bell peppers", "black pepper", "cumin", "eggs", "feta", "garlic", "mixed herbs", "olive oil", "onions", "paprika", "passata", "salt", "tortillas"]'::jsonb, recipe = $r${"steps": ["Dice 1 onion and 2 bell peppers and chop 2 garlic cloves. Heat 1 tbsp olive oil in a large frying pan with a lid over medium heat.", "Cook the onion and peppers for 7 minutes until soft, then the garlic for 1 minute.", "Stir in 1 tsp paprika, 1 tsp cumin, ½ tsp mixed herbs, ½ tsp salt and ¼ tsp black pepper for 30 seconds.", "Pour in 400g passata and simmer for 6 minutes until slightly thickened.", "Make 4 wells and crack an egg into each. Cover and cook on low for 5–6 minutes until the whites are set and the yolks still soft.", "Warm 4 tortillas in a dry pan for 30 seconds per side. Crumble 80g feta over the shakshuka and serve from the pan with the tortillas for scooping."], "tip": "Frying the spices for 30 seconds before the passata makes the whole dish taste deeper."}$r$::jsonb where name = 'Shakshuka';
update public.meals set time = 15, ing = '["black pepper", "chilli flakes", "garlic", "olive oil", "parmesan", "salt", "spaghetti", "spinach"]'::jsonb, recipe = $r${"steps": ["Cook 180g spaghetti in salted boiling water for 9–10 minutes. Keep a mug of pasta water, then drain.", "Meanwhile, thinly slice 4 garlic cloves. Warm 4 tbsp olive oil in a large frying pan over medium-low heat.", "Add the garlic and ½ tsp chilli flakes and cook gently for 2 minutes until pale gold — don't let it brown.", "Add 150g spinach in handfuls and stir until wilted.", "Add the drained spaghetti and 100ml pasta water and toss for 1 minute until the oil and water come together into a glossy coating.", "Season with salt and plenty of black pepper, and serve with 30g grated parmesan."], "tip": "Browned garlic is bitter — keep the heat low and pull it as soon as it turns golden."}$r$::jsonb where name = 'Spaghetti aglio e olio with spinach';
update public.meals set time = 35, ing = '["black pepper", "eggs", "olive oil", "onions", "paprika", "potatoes", "salt", "tomatoes"]'::jsonb, recipe = $r${"steps": ["Peel 400g potatoes and slice thinly (about 3mm). Thinly slice 1 onion.", "Heat 4 tbsp olive oil in a 20cm non-stick frying pan over medium-low heat. Add the potatoes and onion with ½ tsp salt and cook gently for 15 minutes, turning occasionally, until soft but not browned.", "Beat 5 eggs with ½ tsp paprika, a pinch of salt and black pepper. Tip the potatoes into the eggs and mix.", "Wipe the pan, add 1 tbsp olive oil and return the mixture. Cook on low for 8 minutes until the edges are set and the centre still wobbles.", "Put a plate over the pan, flip the tortilla onto it, then slide it back in and cook for 3 minutes more.", "Dice 3 tomatoes and dress with 1 tbsp olive oil, salt, pepper and a pinch of paprika.", "Cut the tortilla into wedges and serve warm with the tomato salad."], "tip": "A slight wobble in the middle before flipping gives a creamy centre."}$r$::jsonb where name = 'Spanish tortilla with tomato salad';
update public.meals set time = 30, ing = '["black pepper", "chilli flakes", "coconut milk", "cumin", "curry paste", "garlic", "olive oil", "onions", "paprika", "potatoes", "rice", "salt", "spinach", "stock cubes"]'::jsonb, recipe = $r${"steps": ["Rinse 150g rice and cook in 300ml water with a pinch of salt: boil, cover, simmer on the lowest heat for 12 minutes, then rest covered.", "Cut 500g potatoes into 2cm chunks, dice 1 onion and chop 2 garlic cloves.", "Heat 1 tbsp olive oil in a large pan over medium heat and cook the onion for 4 minutes, then the garlic, 2 tbsp curry paste, 1 tsp cumin and 1 tsp paprika for 1 minute.", "Add the potatoes, a 400ml tin of coconut milk, 200ml water and 1 crumbled stock cube. Cover and simmer for 15 minutes until the potatoes are tender.", "Stir in 150g spinach until wilted, about 2 minutes.", "Season with salt, black pepper and ½ tsp chilli flakes, and serve over the rice."], "tip": "Crumble the stock cube in finely so it dissolves evenly through the sauce."}$r$::jsonb where name = 'Spiced potato & spinach curry';
update public.meals set time = 20, ing = '["black pepper", "eggs", "feta", "olive oil", "paprika", "potatoes", "salt", "spinach"]'::jsonb, recipe = $r${"steps": ["Dice 300g potatoes into 1cm cubes. Heat 2 tbsp olive oil in a large non-stick frying pan over medium-high heat and cook the potatoes for 10 minutes, turning, until golden and tender. Season with salt.", "Add 150g spinach and stir for 1 minute until wilted.", "Beat 5 eggs with ½ tsp paprika, a pinch of salt and black pepper.", "Turn the heat to medium-low, pour in the eggs and scatter over 100g crumbled feta.", "Cook for 3 minutes, pushing the set edges towards the middle so the runny egg flows underneath.", "When the top is just set, fold in half, cut into two and serve with black pepper."], "tip": "Fold rather than flip — it keeps the filling in and the middle soft."}$r$::jsonb where name = 'Spinach & feta omelette with potatoes';
update public.meals set time = 35, ing = '["black pepper", "chicken thighs", "chilli flakes", "cumin", "curry paste", "garlic", "lemons", "olive oil", "onions", "paprika", "rice", "salt", "stock cubes", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Mix 150g yoghurt with 2 tbsp curry paste, 2 grated garlic cloves, 1 tsp cumin, 1 tsp paprika, ½ tsp chilli flakes, the juice of half a lemon, ½ tsp salt and ¼ tsp black pepper.", "Slash 4 chicken thighs a couple of times and coat in the marinade. Leave for 10 minutes (or up to overnight in the fridge).", "Preheat the grill to high. Line a tray, lay the chicken on it and grill for 20 minutes, turning once, until charred and cooked through.", "Meanwhile, dice 1 onion and cook in 1 tbsp olive oil over medium heat for 4 minutes. Add 150g rinsed rice and stir for 1 minute.", "Add 300ml water and 1 crumbled stock cube, bring to the boil, cover and simmer on the lowest heat for 12 minutes. Rest covered for 5 minutes.", "Serve the chicken on the rice with the remaining lemon cut into wedges."], "tip": "Slashing the chicken lets the marinade get in and helps it cook faster under the grill."}$r$::jsonb where name = 'Tandoori-style yoghurt chicken with rice';
update public.meals set time = 35, ing = '["black pepper", "garlic", "mixed herbs", "olive oil", "onions", "parmesan", "passata", "rice", "salt", "stock cubes"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 200°C (180°C fan). Dice 1 onion and chop 2 garlic cloves.", "Heat 2 tbsp olive oil in an ovenproof pan with a lid over medium heat. Cook the onion for 4 minutes, then the garlic for 1 minute.", "Add 150g rice and stir for 1 minute to coat.", "Pour in 300g passata and 300ml water with 1 crumbled stock cube. Add 1 tsp mixed herbs, ¼ tsp salt and black pepper and bring to a simmer.", "Cover and bake for 22 minutes until the rice is tender and the liquid absorbed.", "Stir in 40g grated parmesan, rest for 2 minutes and serve with extra parmesan and black pepper."], "tip": "If the rice still has bite at 22 minutes, add a splash of water and give it 5 more minutes covered."}$r$::jsonb where name = 'Tomato & parmesan baked rice';
update public.meals set time = 20, ing = '["black pepper", "garlic", "mixed herbs", "olive oil", "parmesan", "passata", "salt", "spaghetti", "tomatoes"]'::jsonb, recipe = $r${"steps": ["Cook 180g spaghetti in salted boiling water for 9–10 minutes. Keep a mug of pasta water, then drain.", "Meanwhile, thinly slice 3 garlic cloves and dice 3 tomatoes.", "Heat 3 tbsp olive oil in a large pan over medium heat and cook the garlic for 1 minute until fragrant.", "Add the tomatoes and cook for 3 minutes until they start to break down, then pour in 250g passata and 1 tsp mixed herbs. Simmer for 5 minutes.", "Season with ½ tsp salt and black pepper. Add the spaghetti and a splash of pasta water and toss for 1 minute.", "Serve with 30g grated parmesan."], "tip": "Keep the pasta al dente — it finishes cooking in the sauce."}$r$::jsonb where name = 'Veggie spaghetti pomodoro';
update public.meals set time = 25, ing = '["black pepper", "chickpeas", "chopped tomatoes", "cumin", "eggs", "garlic", "olive oil", "onions", "paprika", "salt", "spinach", "tortillas"]'::jsonb, recipe = $r${"steps": ["Dice 1 onion and chop 2 garlic cloves. Heat 2 tbsp olive oil in a large frying pan with a lid over medium heat and cook the onion for 5 minutes, then the garlic for 1 minute.", "Stir in 1 tsp paprika and ½ tsp cumin for 30 seconds.", "Add a 400g tin of chopped tomatoes, a drained 400g tin of chickpeas, ½ tsp salt and ¼ tsp black pepper. Simmer for 7 minutes until thickened.", "Stir in 150g spinach until wilted.", "Make 4 wells and crack an egg into each. Cover and cook on low for 6 minutes until the whites are set and the yolks still soft.", "Warm 4 tortillas in a dry pan for 30 seconds per side and serve alongside for scooping."], "tip": "Keep the heat low once the eggs are in so the sauce doesn't catch underneath before the whites set."}$r$::jsonb where name = 'Baked Eggs in Tomato & Chickpea Sauce with Spinach';
update public.meals set time = 25, ing = '["black pepper", "chickpeas", "eggs", "garlic", "mixed herbs", "olive oil", "onions", "passata", "salt", "spinach", "tortillas"]'::jsonb, recipe = $r${"steps": ["Dice 1 onion and chop 2 garlic cloves. Heat 2 tbsp olive oil in a large frying pan with a lid over medium heat and cook the onion for 5 minutes, then the garlic for 1 minute.", "Add 300g passata, a drained 400g tin of chickpeas, 1 tsp mixed herbs, ½ tsp salt and ¼ tsp black pepper. Simmer for 5 minutes.", "Stir in 150g spinach until wilted.", "Make 4 wells and crack an egg into each. Cover and cook on low for 6 minutes until the whites are set and the yolks still soft.", "Warm 4 tortillas in a dry pan for 30 seconds per side.", "Finish with a drizzle of olive oil and black pepper and serve from the pan with the tortillas."], "tip": "Crush a few chickpeas into the sauce with the back of a spoon to thicken it."}$r$::jsonb where name = 'Baked Eggs with Chickpea Tomato Sauce';
update public.meals set time = 40, ing = '["black pepper", "eggs", "feta", "garlic", "olive oil", "paprika", "potatoes", "salt", "spinach"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 220°C (200°C fan). Halve 2 large baking potatoes (about 600g) lengthways, rub with 1 tbsp olive oil, salt and ½ tsp paprika, and roast cut-side down on a tray for 30 minutes until tender.", "Chop 2 garlic cloves. Heat 1 tbsp olive oil in a frying pan over medium heat, cook the garlic for 30 seconds, then add 200g spinach and stir until wilted and the liquid has cooked off, about 3 minutes.", "Take off the heat and stir in 100g crumbled feta and black pepper.", "Turn the potato halves cut-side up, fluff the insides with a fork and press a hollow into each.", "Pile the spinach and feta on top, then crack 1 egg into the hollow of each half (4 eggs). Season with salt, pepper and a pinch of paprika.", "Return to the oven for 8 minutes until the whites are set and the yolks still soft. Serve 2 halves each."], "tip": "Roasting the potatoes cut-side down gets them cooked in 30 minutes instead of an hour."}$r$::jsonb where name = 'Baked Potatoes with Feta & Spinach Topping';
update public.meals set time = 25, ing = '["black pepper", "broccoli", "garlic", "lemons", "olive oil", "paprika", "rice", "salmon fillet", "salt"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 220°C (200°C fan). Rinse 150g rice and cook in 300ml water with a pinch of salt: boil, cover, simmer on the lowest heat for 12 minutes, then rest covered.", "Cut 1 head of broccoli into florets and toss on a tray with 2 tbsp olive oil, 2 chopped garlic cloves, salt and black pepper. Roast for 5 minutes.", "Pat 2 salmon fillets dry, rub with 1 tbsp olive oil, ½ tsp paprika, salt and pepper, and add to the tray skin-side down. Top with 3 thin lemon slices.", "Roast for 12 minutes until the salmon flakes and the broccoli is charred at the edges.", "Serve on the rice with the juice of the remaining lemon squeezed over."], "tip": "Give the broccoli a 5-minute head start so it chars while the salmon stays just cooked."}$r$::jsonb where name = 'Baked Salmon with Roasted Broccoli & Lemon';
update public.meals set time = 25, ing = '["black pepper", "broccoli", "chilli flakes", "garlic", "minced beef", "mixed herbs", "olive oil", "parmesan", "salt", "spaghetti"]'::jsonb, recipe = $r${"steps": ["Cook 180g spaghetti in salted boiling water for 9–10 minutes. Cut 1 head of broccoli into small florets and drop them in for the last 3 minutes. Keep a mug of pasta water, then drain.", "Meanwhile, heat 1 tbsp olive oil in a large frying pan over high heat. Cook 300g minced beef for 6 minutes, breaking it up, until browned. Season with 1 tsp mixed herbs, ½ tsp salt and ¼ tsp black pepper and tip onto a plate.", "Lower the heat, add 3 tbsp olive oil, 4 sliced garlic cloves and ½ tsp chilli flakes, and cook gently for 2 minutes until golden.", "Return the beef, add the pasta and broccoli and a splash of pasta water, and toss for 1 minute.", "Serve with 30g grated parmesan and black pepper."], "tip": "Cook the garlic gently — the oil should taste sweet and garlicky, not bitter."}$r$::jsonb where name = 'Beef & Broccoli Spaghetti with Garlic Oil';
update public.meals set time = 30, ing = '["black pepper", "butter", "garlic", "minced beef", "mixed herbs", "olive oil", "onions", "parmesan", "passata", "potatoes", "salt", "spinach"]'::jsonb, recipe = $r${"steps": ["Peel 600g potatoes, cut into chunks and boil in salted water for 15 minutes until tender.", "Dice 1 onion and chop 2 garlic cloves. Heat 1 tbsp olive oil in a large frying pan over medium-high heat and cook the onion for 4 minutes.", "Add 300g minced beef and cook for 6 minutes, breaking it up, until browned. Stir in the garlic and 1 tsp mixed herbs for 1 minute.", "Add 200g passata, ½ tsp salt and ¼ tsp black pepper and simmer for 5 minutes into a thick, saucy mince.", "Drain the potatoes and mash with 25g butter, 40g grated parmesan, salt and pepper.", "Push the mince to one side, add 150g spinach to the pan and stir for 2 minutes until wilted.", "Serve the mince and spinach over the mash with extra parmesan."], "tip": "Mash the potatoes while they're hot and let them steam off for a minute first — wet potatoes make gluey mash."}$r$::jsonb where name = 'Beef & Parmesan Mash with Sautéed Spinach';
update public.meals set time = 30, ing = '["black pepper", "chilli flakes", "coconut milk", "cumin", "curry paste", "fresh coriander", "garlic", "minced beef", "olive oil", "onions", "paprika", "potatoes", "salt", "stock cubes", "tortillas", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Dice 1 onion, chop 2 garlic cloves and cut 300g potatoes into 1cm cubes.", "Heat 1 tbsp olive oil in a large pan with a lid over medium-high heat and cook the onion for 4 minutes.", "Add 300g minced beef and cook for 5 minutes, breaking it up, until browned.", "Stir in the garlic, 2 tbsp curry paste, 1 tsp cumin, 1 tsp paprika and ½ tsp chilli flakes for 1 minute.", "Add the potatoes, 200ml coconut milk (half a tin) and 1 crumbled stock cube. Cover and simmer for 15 minutes, stirring occasionally, until the potatoes are tender and the sauce is thick.", "Season with salt and black pepper. Warm 4 tortillas in a dry pan for 30 seconds per side.", "Fill the tortillas with the curry, top with a spoon of yoghurt and chopped fresh coriander, and serve."], "tip": "Keep the potato cubes small so they cook through in 15 minutes and soak up the sauce."}$r$::jsonb where name = 'Beef & Potato Curry Tacos';
update public.meals set time = 30, ing = '["bell peppers", "black pepper", "chopped tomatoes", "cumin", "minced beef", "mixed herbs", "olive oil", "onions", "paprika", "parmesan", "salt", "tortillas"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 200°C (180°C fan). Dice 1 onion and 1 bell pepper.", "Heat 1 tbsp olive oil in a frying pan over medium-high heat. Brown 300g minced beef for 5 minutes, breaking it up.", "Add the onion and pepper and cook for 4 minutes until soft.", "Stir in 1 tsp cumin, 1 tsp paprika, 1 tsp mixed herbs, ½ tsp salt and ¼ tsp black pepper, then a 400g tin of chopped tomatoes. Simmer for 5 minutes until thick.", "Spread a thin layer of the beef in a small baking dish. Cover with a tortilla (tear to fit), then more beef, and repeat, using 4 tortillas and finishing with beef on top.", "Sprinkle 40g grated parmesan over the top and bake for 15 minutes until golden and bubbling. Cut into portions to serve."], "tip": "Make the beef layer properly thick, not runny — a wet sauce turns the tortillas soggy."}$r$::jsonb where name = 'Beef & Tomato Tortilla Casserole';
update public.meals set time = 30, ing = '["black pepper", "eggs", "garlic", "lemons", "minced beef", "mixed herbs", "olive oil", "onions", "parmesan", "rice", "salt", "spinach", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 200°C (180°C fan). Rinse 150g rice and cook in 300ml water with a pinch of salt: boil, cover, simmer on the lowest heat for 12 minutes, then rest covered.", "Finely grate ½ onion and 2 garlic cloves. Mix with 400g minced beef, 1 egg, 30g grated parmesan, 1 tsp mixed herbs, ½ tsp salt and ¼ tsp black pepper until just combined.", "Roll into 12 meatballs, place on a lined tray, drizzle with 1 tbsp olive oil and bake for 18 minutes until browned and cooked through.", "Mix 200g yoghurt with the zest and juice of half a lemon, 1 tsp mixed herbs, a pinch of salt and pepper.", "Heat 1 tbsp olive oil in a frying pan and wilt 150g spinach for 2 minutes with a pinch of salt.", "Serve the meatballs on the rice with the spinach, the lemon herb yoghurt spooned over, and the remaining lemon in wedges."], "tip": "Grating the onion rather than dicing it keeps the meatballs tender and helps them hold together."}$r$::jsonb where name = 'Beef Meatballs with Lemon Herb Yoghurt';
update public.meals set time = 30, ing = '["black pepper", "eggs", "garlic", "minced beef", "mixed herbs", "olive oil", "onions", "parmesan", "salt", "spinach", "tomatoes", "tortillas", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 200°C (180°C fan). Finely grate ½ onion and 2 garlic cloves.", "Mix 400g minced beef with the grated onion, half the garlic, 1 egg, 30g grated parmesan, 1 tsp mixed herbs, ½ tsp salt and ¼ tsp black pepper until just combined.", "Roll into 12 meatballs, place on a lined tray, drizzle with 1 tbsp olive oil and bake for 18 minutes until browned and cooked through.", "Mix 200g yoghurt with the remaining garlic, 1 tsp mixed herbs, a pinch of salt and pepper.", "Dice 2 tomatoes and thinly slice the remaining ½ onion.", "Warm 4 tortillas in a dry pan for 30 seconds per side.", "Fill each tortilla with a handful of spinach, 3 meatballs, tomato and onion, and a generous spoon of the garlic herb yoghurt. Roll and serve."], "tip": "Rest the meatballs for 2 minutes out of the oven so they stay juicy when you cut into them."}$r$::jsonb where name = 'Beef Meatballs with Yoghurt & Herbs';
update public.meals set time = 40, ing = '["bell peppers", "black pepper", "chicken thighs", "garlic", "mixed herbs", "olive oil", "onions", "parmesan", "passata", "salt", "spaghetti"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 200°C (180°C fan). Cook 180g spaghetti in salted boiling water for 8 minutes (slightly under), then drain.", "Meanwhile, cut 4 boneless chicken thighs into chunks and season with ½ tsp salt, ¼ tsp black pepper and 1 tsp mixed herbs. Heat 1 tbsp olive oil in a large frying pan over medium-high heat and brown the chicken for 6 minutes. Set aside.", "Dice 1 onion and 2 bell peppers and chop 3 garlic cloves. Add 1 tbsp olive oil to the pan and cook the onion and peppers for 5 minutes, then the garlic for 1 minute.", "Pour in 400g passata and 100ml water, return the chicken and simmer for 3 minutes. Season to taste.", "Toss the spaghetti through the sauce, tip into a baking dish and scatter over 40g grated parmesan.", "Bake for 15 minutes until golden on top. Rest for 2 minutes and serve."], "tip": "Undercook the spaghetti slightly — it finishes in the oven and soaks up the sauce."}$r$::jsonb where name = 'Chicken & Bell Pepper Pasta Bake';
update public.meals set time = 30, ing = '["bell peppers", "black pepper", "chicken thighs", "chilli flakes", "cumin", "fresh coriander", "garlic", "lemons", "olive oil", "onions", "paprika", "salt", "tortillas", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Cut 4 boneless chicken thighs into strips and toss with 1 tsp cumin, 1 tsp paprika, ½ tsp chilli flakes, ½ tsp salt and ¼ tsp black pepper.", "Heat 1 tbsp olive oil in a large frying pan over high heat. Cook the chicken for 8 minutes, turning, until charred and cooked through. Set aside.", "Slice 1 onion and 2 bell peppers into strips and chop 2 garlic cloves. Add 1 tbsp olive oil to the pan and cook the onion and peppers for 6 minutes until soft and charred, then the garlic for 1 minute.", "Return the chicken, squeeze over the juice of half a lemon and toss for 1 minute.", "Mix 4 tbsp yoghurt with the remaining lemon juice and a pinch of salt. Warm 4 tortillas in a dry pan for 30 seconds per side.", "Serve the chicken and peppers in the tortillas with the lemon yoghurt and chopped fresh coriander."], "tip": "Don't stir the peppers too often — they need contact with the hot pan to char."}$r$::jsonb where name = 'Chicken Thigh Fajita Tortillas';
update public.meals set time = 25, ing = '["black pepper", "chickpeas", "chopped tomatoes", "coconut milk", "garlic", "mixed herbs", "olive oil", "onions", "salt", "spaghetti"]'::jsonb, recipe = $r${"steps": ["Cook 180g spaghetti in salted boiling water for 9–10 minutes. Keep a mug of pasta water, then drain.", "Meanwhile, dice 1 onion and chop 3 garlic cloves. Heat 2 tbsp olive oil in a large pan over medium heat and cook the onion for 5 minutes, then the garlic for 1 minute.", "Add a 400g tin of chopped tomatoes and 1 tsp mixed herbs and simmer for 4 minutes.", "Add 200ml coconut milk (half a tin) and a drained 400g tin of chickpeas. Simmer for 5 minutes until creamy.", "Season with ½ tsp salt and black pepper. Toss the spaghetti through, loosening with pasta water if needed, and serve."], "tip": "Half a tin of coconut milk is enough — a full tin drowns the tomato."}$r$::jsonb where name = 'Chickpea & Tomato Coconut Pasta';
update public.meals set time = 20, ing = '["black pepper", "chickpeas", "garlic", "mixed herbs", "olive oil", "parmesan", "passata", "salt", "spaghetti", "spinach"]'::jsonb, recipe = $r${"steps": ["Cook 180g spaghetti in salted boiling water for 9–10 minutes. Keep a mug of pasta water, then drain.", "Meanwhile, heat 2 tbsp olive oil in a large pan over medium heat. Cook 3 chopped garlic cloves for 1 minute.", "Add 300g passata, a drained 400g tin of chickpeas, 1 tsp mixed herbs, ½ tsp salt and ¼ tsp black pepper. Simmer for 4 minutes, crushing about a third of the chickpeas against the pan to thicken.", "Stir in 150g spinach until wilted.", "Add the spaghetti, 30g grated parmesan and a splash of pasta water. Toss until creamy and serve with extra parmesan."], "tip": "Crushed chickpeas plus parmesan and pasta water give the creaminess — no cream needed."}$r$::jsonb where name = 'Creamy Chickpea & Tomato Pasta';
update public.meals set time = 40, ing = '["black pepper", "feta", "garlic", "olive oil", "paprika", "potatoes", "salt", "spinach", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 220°C (200°C fan). Halve 2 large baking potatoes (about 600g) lengthways, rub with 1 tbsp olive oil, salt and ½ tsp paprika, and roast cut-side down for 30 minutes until tender.", "Chop 2 garlic cloves. Heat 1 tbsp olive oil in a frying pan over medium heat, cook the garlic for 30 seconds, then add 200g spinach and stir until wilted and dry, about 3 minutes.", "Take off the heat and stir in 100g yoghurt, 100g crumbled feta and black pepper.", "Scoop most of the flesh from the potato halves into the spinach mix, leaving a 1cm shell, and mash it in.", "Pile the filling back into the shells, top with 50g more feta and return to the oven for 8 minutes until golden.", "Finish with a pinch of paprika and black pepper and serve."], "tip": "Roast the potatoes cut-side down — it halves the cooking time and crisps the skin."}$r$::jsonb where name = 'Creamy Spinach & Feta Baked Potatoes';
update public.meals set time = 35, ing = '["black pepper", "chicken thighs", "chopped tomatoes", "feta", "garlic", "olive oil", "onions", "paprika", "salt", "spinach", "tortillas"]'::jsonb, recipe = $r${"steps": ["Pat 4 chicken thighs dry and season with 1 tsp paprika, ½ tsp salt and ¼ tsp black pepper.", "Heat 1 tbsp olive oil in a large frying pan over medium-high heat. Cook skin-side down for 7 minutes until crisp, flip and cook 6 minutes more until cooked through. Rest on a plate, then shred with two forks.", "Dice 1 onion and chop 2 garlic cloves. Cook in the pan fat for 4 minutes until soft.", "Add a 400g tin of chopped tomatoes, ½ tsp salt and pepper. Simmer for 6 minutes until thick.", "Warm 4 tortillas in a dry pan for 30 seconds per side.", "Build two stacks: tortilla, sauce, shredded chicken, a little spinach and crumbled feta; repeat, finishing with sauce and feta (100g feta in total). Cut in half and serve."], "tip": "Don't move the chicken while the skin is down — that's where the crispness comes from."}$r$::jsonb where name = 'Crispy Chicken Thigh Tortilla Stack with Tomato & Feta';
update public.meals set time = 20, ing = '["black pepper", "broccoli", "garlic", "halloumi", "lemons", "olive oil", "paprika", "salt", "tortillas", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Cut 1 head of broccoli into small florets and chop 2 garlic cloves. Slice a 225g block of halloumi into 8 slices and pat dry.", "Heat 1 tbsp olive oil in a large frying pan over medium-high heat. Add the broccoli and 3 tbsp water, cover and cook for 4 minutes.", "Uncover, add the garlic, 1 tsp paprika, a pinch of salt and black pepper, and cook for 2 minutes until the edges catch. Tip onto a plate.", "Add 1 tbsp olive oil and fry the halloumi for 2 minutes per side until golden.", "Mix 4 tbsp yoghurt with the juice of half a lemon and a pinch of salt. Warm 4 tortillas in a dry pan for 30 seconds per side.", "Spread the tortillas with lemon yoghurt, add the broccoli and halloumi, squeeze over the remaining lemon, roll tightly and serve."], "tip": "Leave the halloumi untouched for the full 2 minutes per side to get a proper crust."}$r$::jsonb where name = 'Crispy Halloumi & Broccoli Tortilla Wraps';
update public.meals set time = 20, ing = '["black pepper", "garlic", "halloumi", "mixed herbs", "olive oil", "salt", "spaghetti", "tomatoes"]'::jsonb, recipe = $r${"steps": ["Cook 180g spaghetti in salted boiling water for 9–10 minutes. Keep a mug of pasta water, then drain.", "Slice a 225g block of halloumi into 8 slices and pat dry. Heat 1 tbsp olive oil in a large frying pan over medium-high heat and fry for 2 minutes per side until golden. Set aside.", "Halve 300g cherry tomatoes (or dice 3 tomatoes) and chop 3 garlic cloves. Add 2 tbsp olive oil to the pan and cook the garlic for 30 seconds.", "Add the tomatoes, 1 tsp mixed herbs, ¼ tsp salt and black pepper. Cook for 5 minutes until they burst and go saucy.", "Toss the spaghetti through with a splash of pasta water. Top with the halloumi and a drizzle of olive oil and serve."], "tip": "Halloumi is salty, so go easy on the salt in the sauce and taste before adding more."}$r$::jsonb where name = 'Crispy Halloumi & Tomato Spaghetti';
update public.meals set time = 50, ing = '["bell peppers", "black pepper", "chicken thighs", "chilli flakes", "coconut milk", "cumin", "curry paste", "olive oil", "onions", "paprika", "potatoes", "salt", "stock cubes"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 200°C (180°C fan). Cut 500g potatoes into 2cm chunks, 1 onion into wedges and 2 bell peppers into chunks. Toss in a roasting tin with 1 tbsp olive oil, salt and black pepper.", "Mix 2 tbsp curry paste with 1 tsp cumin, 1 tsp paprika, ½ tsp chilli flakes and 1 tbsp olive oil. Rub over 4 chicken thighs and sit them skin-side up on the vegetables.", "Whisk a 400ml tin of coconut milk with 1 crumbled stock cube and pour around (not over) the chicken.", "Cover with foil and roast for 25 minutes.", "Uncover and roast for 15 minutes more until the chicken skin is golden and the potatoes are tender.", "Season the sauce with salt and pepper and serve from the tin."], "tip": "Pour the coconut milk around the chicken, not on it, so the skin roasts instead of steaming."}$r$::jsonb where name = 'Curried Chicken Thigh & Potato Traybake with Coconut';
update public.meals set time = 25, ing = '["black pepper", "chickpeas", "chilli flakes", "chopped tomatoes", "coconut milk", "cumin", "curry paste", "fresh coriander", "garlic", "olive oil", "onions", "paprika", "salt", "stock cubes"]'::jsonb, recipe = $r${"steps": ["Dice 1 onion and chop 2 garlic cloves. Heat 1 tbsp olive oil in a large pot over medium heat and cook the onion for 4 minutes, then the garlic for 1 minute.", "Stir in 2 tbsp curry paste, 1 tsp cumin and ½ tsp paprika for 1 minute.", "Add a 400g tin of chopped tomatoes and cook for 2 minutes.", "Pour in a 400ml tin of coconut milk and 300ml water, crumble in 1 stock cube and add a drained 400g tin of chickpeas.", "Simmer for 10 minutes until slightly thickened. Blend half with a stick blender if you want it thicker.", "Season with salt, black pepper and ¼ tsp chilli flakes. Serve in bowls topped with chopped fresh coriander."], "tip": "Taste before adding the chilli flakes — the curry paste already brings some heat."}$r$::jsonb where name = 'Curried Chickpea & Tomato Coconut Soup';
update public.meals set time = 40, ing = '["black pepper", "broccoli", "chilli flakes", "coconut milk", "cumin", "curry paste", "olive oil", "paprika", "potatoes", "salmon fillet", "salt", "stock cubes"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 220°C (200°C fan). Cut 500g potatoes into 2cm cubes and toss on a large tray with 2 tbsp olive oil, ½ tsp paprika, salt and black pepper. Roast for 20 minutes.", "Meanwhile, make the sauce: in a small pan, whisk 2 tbsp curry paste with 200ml coconut milk (half a tin), ½ crumbled stock cube and ½ tsp cumin. Simmer for 5 minutes until thickened.", "Cut 1 head of broccoli into florets and toss with 1 tbsp olive oil and a pinch of salt.", "Push the potatoes to one side of the tray, add the broccoli and lay 2 salmon fillets skin-side down in the middle. Spoon half the sauce over the salmon and sprinkle with ¼ tsp chilli flakes.", "Roast for 13 minutes until the salmon flakes.", "Plate the potatoes, broccoli and salmon and spoon the rest of the warm sauce over."], "tip": "Don't stir the potatoes once they're roasting — leaving them alone gives crisp edges."}$r$::jsonb where name = 'Curried Salmon with Roasted Potatoes & Broccoli';
update public.meals set time = 35, ing = '["black pepper", "chicken thighs", "chopped tomatoes", "garlic", "mixed herbs", "olive oil", "onions", "parmesan", "salt", "spaghetti"]'::jsonb, recipe = $r${"steps": ["Pat 4 chicken thighs dry and season with ½ tsp salt and ¼ tsp black pepper. Heat 1 tbsp olive oil in a large pan with a lid over medium-high heat and cook skin-side down for 6 minutes until golden, then flip for 3 minutes. Set aside.", "Dice 1 onion and chop 4 garlic cloves. Cook in the pan for 4 minutes until soft.", "Add a 400g tin of chopped tomatoes, 100ml water and 1 tsp mixed herbs. Return the chicken, cover and simmer for 15 minutes until cooked through.", "Meanwhile, cook 180g spaghetti in salted boiling water for 9–10 minutes and drain.", "Lift out the chicken, shred it with two forks (discard the skin if you prefer) and stir back into the sauce. Season with salt and pepper.", "Toss the spaghetti through the sauce and serve with 30g grated parmesan."], "tip": "Searing the thighs skin-side down first renders the fat that flavours the whole sauce."}$r$::jsonb where name = 'Garlic Tomato Chicken Thigh Spaghetti';
update public.meals set time = 20, ing = '["black pepper", "chopped tomatoes", "garlic", "halloumi", "mixed herbs", "olive oil", "onions", "salt", "spaghetti"]'::jsonb, recipe = $r${"steps": ["Cook 180g spaghetti in salted boiling water for 9–10 minutes. Keep a mug of pasta water, then drain.", "Dice 1 onion and chop 3 garlic cloves. Heat 2 tbsp olive oil in a large pan over medium heat and cook the onion for 4 minutes, then the garlic for 1 minute.", "Add a 400g tin of chopped tomatoes, 1 tsp mixed herbs, ¼ tsp salt and ¼ tsp black pepper. Simmer for 6 minutes until thick.", "Cut a 225g block of halloumi into 1cm cubes and pat dry. Heat 1 tbsp olive oil in a frying pan over medium-high heat and fry for 3 minutes, turning, until golden.", "Toss the spaghetti through the sauce with a splash of pasta water, fold in the halloumi and serve with black pepper."], "tip": "Add the halloumi at the very end so it stays crisp instead of softening in the sauce."}$r$::jsonb where name = 'Garlic Tomato Halloumi Spaghetti';
update public.meals set time = 20, ing = '["bell peppers", "black pepper", "chickpeas", "garlic", "halloumi", "lemons", "olive oil", "paprika", "salt", "spinach", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Slice a 225g block of halloumi into 8 slices and pat dry. Heat 1 tbsp olive oil in a large frying pan over medium-high heat and fry for 2 minutes per side until golden. Set aside.", "Drain a 400g tin of chickpeas and pat dry. Add 1 tbsp olive oil to the pan, then the chickpeas with 1 tsp paprika, ¼ tsp salt and black pepper. Fry for 4 minutes until lightly crisp.", "Dice 2 bell peppers.", "Mix 150g yoghurt with 1 finely grated garlic clove, the juice of half a lemon, a pinch of salt and pepper.", "Divide 100g spinach between two bowls. Top with the chickpeas, peppers and halloumi.", "Spoon over the dressing, squeeze over the remaining lemon and finish with a pinch of paprika."], "tip": "Dry the chickpeas well before frying so they crisp instead of spitting."}$r$::jsonb where name = 'Halloumi & Chickpea Buddha Bowl with Yoghurt Dressing';
update public.meals set time = 30, ing = '["bell peppers", "black pepper", "garlic", "halloumi", "lemons", "mixed herbs", "olive oil", "paprika", "passata", "potatoes", "salt"]'::jsonb, recipe = $r${"steps": ["Cut 400g potatoes into 3cm chunks and boil in salted water for 10 minutes until just tender. Drain and steam dry.", "Cut a 225g block of halloumi into 3cm cubes and 2 bell peppers into similar chunks. Toss everything with 2 tbsp olive oil, 1 tsp paprika, 1 tsp mixed herbs and black pepper.", "Thread onto 4 skewers, alternating potato, halloumi and pepper. (No skewers? Cook the pieces loose in the pan — it works just as well.)", "Heat 1 tbsp olive oil in a large frying pan or griddle over medium-high heat. Cook the skewers for 10 minutes, turning every 2–3 minutes, until the halloumi is golden and the potatoes are crisp.", "Meanwhile, cook 1 chopped garlic clove in 1 tbsp olive oil for 30 seconds, add 250g passata, ½ tsp mixed herbs, ¼ tsp salt and pepper, and simmer for 5 minutes.", "Squeeze the juice of 1 lemon over the skewers and serve with the warm tomato sauce for dipping."], "tip": "If you use wooden skewers, soak them in water for 20 minutes first so they don't scorch."}$r$::jsonb where name = 'Halloumi & Potato Skewers with Tomato Sauce';
update public.meals set time = 30, ing = '["bell peppers", "black pepper", "coconut milk", "garlic", "minced beef", "olive oil", "onions", "paprika", "rice", "salt", "stock cubes"]'::jsonb, recipe = $r${"steps": ["Dice 1 onion and 2 bell peppers and chop 2 garlic cloves. Rinse 150g rice.", "Heat 1 tbsp olive oil in a large pan with a lid over medium-high heat. Brown 300g minced beef for 5 minutes, breaking it up, then set aside.", "Cook the onion and peppers in the pan for 5 minutes, then the garlic for 1 minute.", "Add the rice, 1 tsp paprika, ½ tsp salt and ¼ tsp black pepper and stir for 1 minute.", "Pour in a 400ml tin of coconut milk and 100ml water with 1 crumbled stock cube. Return the beef and stir.", "Bring to a simmer, cover, and cook on the lowest heat for 15 minutes until the rice is tender. Rest covered for 3 minutes, fluff and serve."], "tip": "Don't lift the lid while the rice cooks — the steam is doing the work."}$r$::jsonb where name = 'Minced Beef & Bell Pepper Coconut Rice';
update public.meals set time = 30, ing = '["black pepper", "chickpeas", "garlic", "minced beef", "mixed herbs", "olive oil", "onions", "parmesan", "passata", "salt", "spaghetti"]'::jsonb, recipe = $r${"steps": ["Dice 1 onion and chop 2 garlic cloves. Heat 1 tbsp olive oil in a large pan over medium-high heat and cook the onion for 4 minutes.", "Add 300g minced beef and cook for 5 minutes, breaking it up, until browned. Stir in the garlic and 1 tsp mixed herbs for 1 minute.", "Add 400g passata, a drained 400g tin of chickpeas, 100ml water, ½ tsp salt and ¼ tsp black pepper.", "Simmer on low for 15 minutes, stirring now and then, until thick.", "Meanwhile, cook 180g spaghetti in salted boiling water for 9–10 minutes and drain.", "Toss the spaghetti through the sauce and serve with 30g grated parmesan."], "tip": "Drain the chickpeas well so they don't water down the sauce."}$r$::jsonb where name = 'Minced Beef & Chickpea Bolognese';
update public.meals set time = 25, ing = '["bell peppers", "black pepper", "chickpeas", "cumin", "garlic", "lemons", "minced beef", "olive oil", "onions", "paprika", "rice", "salt", "yoghurt"]'::jsonb, recipe = $r${"steps": ["Rinse 150g rice and cook in 300ml water with a pinch of salt: boil, cover, simmer on the lowest heat for 12 minutes, then rest covered.", "Dice 1 onion and 2 bell peppers and chop 2 garlic cloves. Heat 1 tbsp olive oil in a large frying pan over medium-high heat and cook the onion for 4 minutes.", "Add 300g minced beef and cook for 6 minutes, breaking it up, until browned.", "Add the peppers, garlic, 1 tsp paprika, 1 tsp cumin, ½ tsp salt and ¼ tsp black pepper. Cook for 4 minutes.", "Stir in a drained 400g tin of chickpeas and the juice of half a lemon and cook for 2 minutes to heat through.", "Serve over the rice with a spoon of yoghurt and the remaining lemon in wedges."], "tip": "A squeeze of lemon at the end lifts the whole bowl — don't skip it."}$r$::jsonb where name = 'Minced Beef & Chickpea Rice Bowl';
update public.meals set time = 30, ing = '["black pepper", "chilli flakes", "coconut milk", "cumin", "curry paste", "fresh coriander", "garlic", "minced beef", "olive oil", "onions", "paprika", "potatoes", "salt", "stock cubes"]'::jsonb, recipe = $r${"steps": ["Dice 1 onion, chop 2 garlic cloves and cut 500g potatoes into 2cm chunks.", "Heat 1 tbsp olive oil in a large pot over medium-high heat and cook the onion for 4 minutes.", "Add 300g minced beef and cook for 5 minutes, breaking it up, until browned.", "Stir in the garlic, 2 tbsp curry paste, 1 tsp cumin, 1 tsp paprika and ¼ tsp chilli flakes for 1 minute.", "Add the potatoes, a 400ml tin of coconut milk, 100ml water and 1 crumbled stock cube. Cover and simmer for 18 minutes until the potatoes are tender.", "Season with salt and black pepper and serve in bowls with chopped fresh coriander."], "tip": "Brown the beef properly before the liquid goes in — that's where the stew gets its depth."}$r$::jsonb where name = 'Minced Beef & Potato Coconut Stew';
update public.meals set time = 25, ing = '["black pepper", "broccoli", "chickpeas", "garlic", "halloumi", "lemons", "mixed herbs", "olive oil", "salt"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 220°C (200°C fan). Cut 1 head of broccoli into florets and toss on a tray with 2 tbsp olive oil, 2 chopped garlic cloves, the zest of 1 lemon, 1 tsp mixed herbs, salt and black pepper. Roast for 15 minutes until charred at the edges.", "Drain a 400g tin of chickpeas and pat dry.", "Slice a 225g block of halloumi into 8 slices and pat dry. Heat 1 tbsp olive oil in a frying pan over medium-high heat and fry for 2 minutes per side until golden.", "Toss the roasted broccoli with the chickpeas, 1 tbsp olive oil, the juice of half the lemon, salt and pepper.", "Divide between plates, top with the halloumi and serve with the remaining lemon in wedges."], "tip": "Roast the broccoli hot and fast so the edges char while the stems stay firm."}$r$::jsonb where name = 'Pan-Seared Halloumi with Lemon Broccoli & Chickpea Salad';
update public.meals set time = 40, ing = '["black pepper", "butter", "garlic", "lemons", "mixed herbs", "olive oil", "onions", "parmesan", "rice", "salmon fillet", "salt", "stock cubes"]'::jsonb, recipe = $r${"steps": ["Dissolve 1 stock cube in 800ml boiling water and keep it hot. Finely dice 1 onion and chop 2 garlic cloves.", "Heat 1 tbsp olive oil and 15g butter in a wide pan over medium heat. Cook the onion for 5 minutes until soft, then the garlic for 1 minute.", "Add 200g rice and stir for 1 minute to coat. Add a ladle of stock and stir until absorbed. Keep adding stock a ladle at a time, stirring often, for 18–20 minutes until the rice is creamy with a little bite.", "Meanwhile, season 2 salmon fillets with salt, black pepper and 1 tsp mixed herbs. Heat 1 tbsp olive oil in a frying pan over medium-high heat and cook skin-side down for 5 minutes, then flip for 2 minutes. Flake into chunks, discarding the skin.", "Take the risotto off the heat and beat in 15g butter, 40g grated parmesan, and the zest and juice of 1 lemon. Season.", "Fold in the salmon gently and serve with extra parmesan and black pepper."], "tip": "Keep the stock hot and add it gradually — cold stock stalls the rice and stops it going creamy."}$r$::jsonb where name = 'Salmon & Lemon Risotto with Parmesan';
update public.meals set time = 25, ing = '["black pepper", "eggs", "olive oil", "onions", "paprika", "potatoes", "salmon fillet", "salt", "spinach"]'::jsonb, recipe = $r${"steps": ["Preheat the oven to 200°C (180°C fan). Dice 300g potatoes into 1cm cubes and 1 onion.", "Heat 2 tbsp olive oil in a 24cm ovenproof frying pan over medium-high heat. Cook the potatoes for 10 minutes, turning, until golden and tender. Add the onion for the last 3 minutes.", "Cut 2 salmon fillets into chunks (skin removed), add to the pan and cook for 2 minutes. Stir in 100g spinach until wilted.", "Beat 6 eggs with ½ tsp salt, ¼ tsp black pepper and ½ tsp paprika. Pour over the pan and cook on the hob for 2 minutes until the edges set.", "Transfer to the oven for 8 minutes until just set in the middle.", "Rest for 2 minutes, slide onto a board, cut in half and serve."], "tip": "Pull it from the oven while the centre still wobbles slightly — it carries on cooking in the pan."}$r$::jsonb where name = 'Salmon & Potato Frittata';
update public.meals set time = 30, ing = '["black pepper", "garlic", "lemons", "olive oil", "paprika", "rice", "salmon fillet", "salt", "spinach"]'::jsonb, recipe = $r${"steps": ["Chop 2 garlic cloves and zest 1 lemon. Heat 2 tbsp olive oil in a large pan with a lid over medium heat and cook the garlic for 1 minute.", "Add 150g rinsed rice and stir for 1 minute. Add 300ml water and ½ tsp salt, bring to the boil, cover and simmer on the lowest heat for 10 minutes.", "Pat 2 salmon fillets dry, remove the skin, and season with salt, black pepper, ½ tsp paprika and the lemon zest.", "Lay the salmon on top of the rice, cover, and cook for 8 minutes more until the salmon flakes and the rice is tender.", "Lift the salmon out. Fold 150g spinach and the juice of half the lemon through the rice until wilted, about 2 minutes.", "Flake the salmon over the rice and serve with the remaining lemon in wedges."], "tip": "Steaming the salmon on top of the rice keeps it moist and saves a pan."}$r$::jsonb where name = 'Salmon & Spinach Rice with Lemon';
update public.meals set time = 25, ing = '["black pepper", "chopped tomatoes", "coconut milk", "garlic", "mixed herbs", "olive oil", "onions", "salmon fillet", "salt", "spaghetti"]'::jsonb, recipe = $r${"steps": ["Cook 180g spaghetti in salted boiling water for 9–10 minutes. Keep a mug of pasta water, then drain.", "Dice 1 onion and chop 2 garlic cloves. Heat 1 tbsp olive oil in a large pan over medium heat and cook the onion for 4 minutes, then the garlic for 1 minute.", "Add a 400g tin of chopped tomatoes and 1 tsp mixed herbs. Simmer for 5 minutes.", "Pour in 200ml coconut milk (half a tin), season with ½ tsp salt and black pepper, and simmer for 2 minutes.", "Cut 2 salmon fillets into chunks (skin removed), add to the sauce and simmer gently for 4 minutes until just cooked.", "Toss the spaghetti through with a splash of pasta water, taking care not to break up the salmon, and serve."], "tip": "Add the salmon last and keep the heat gentle — it only needs 4 minutes."}$r$::jsonb where name = 'Salmon & Tomato Coconut Pasta';
update public.meals set time = 25, ing = '["black pepper", "chilli flakes", "cumin", "curry paste", "halloumi", "olive oil", "onions", "paprika", "rice", "salt", "spinach", "stock cubes", "tomatoes"]'::jsonb, recipe = $r${"steps": ["Dice 1 onion. Heat 1 tbsp olive oil in a large pan with a lid over medium heat and cook the onion for 4 minutes.", "Stir in 1 tbsp curry paste, 1 tsp cumin and 1 tsp paprika for 1 minute.", "Add 150g rinsed rice and stir to coat. Pour in 300ml water with 1 crumbled stock cube, bring to the boil, cover and simmer on the lowest heat for 12 minutes.", "Meanwhile, cut a 225g block of halloumi into cubes and pat dry. Heat 1 tbsp olive oil in a frying pan over medium-high heat and fry for 3 minutes, turning, until golden.", "Dice 2 tomatoes. Fold them and 100g spinach through the rice, cover for 2 minutes until the spinach wilts.", "Season with salt, black pepper and ¼ tsp chilli flakes. Serve topped with the halloumi."], "tip": "Keep the lid on the rice — lifting it lets the steam out and leaves the rice undercooked."}$r$::jsonb where name = 'Spiced Halloumi Rice Bowl with Tomato & Spinach';
update public.meals set time = 30, ing = '["bell peppers", "black pepper", "chilli flakes", "cumin", "curry paste", "minced beef", "olive oil", "onions", "paprika", "rice", "salt", "stock cubes"]'::jsonb, recipe = $r${"steps": ["Dice 1 onion and 2 bell peppers. Heat 1 tbsp olive oil in a large pan with a lid over medium-high heat and cook them for 4 minutes until soft.", "Add 300g minced beef and cook for 5 minutes, breaking it up, until browned.", "Stir in 2 tbsp curry paste, 1 tsp cumin, 1 tsp paprika and ¼ tsp chilli flakes for 1 minute.", "Add 150g rinsed rice and stir for 1 minute to coat.", "Pour in 350ml water with 1 crumbled stock cube and ¼ tsp black pepper. Bring to the boil, cover and simmer on the lowest heat for 15 minutes until the rice is tender.", "Rest covered for 3 minutes, fluff, taste for salt and serve."], "tip": "One stock cube is enough — the curry paste is already salty."}$r$::jsonb where name = 'Spiced Minced Beef & Bell Pepper Rice';
update public.meals set time = 15, ing = '["black pepper", "eggs", "feta", "olive oil", "onions", "paprika", "salt", "spinach", "tortillas"]'::jsonb, recipe = $r${"steps": ["Dice ½ onion. Heat 1 tbsp olive oil in a large frying pan over medium heat and cook the onion for 3 minutes until soft.", "Add 150g spinach and stir for 1 minute until wilted.", "Beat 4 eggs with ½ tsp paprika, a pinch of salt and black pepper. Turn the heat to low, pour in and stir gently for 3 minutes until just set.", "Crumble in 100g feta, fold through and take off the heat.", "Warm 4 tortillas in a dry pan for 30 seconds per side.", "Divide the filling between the tortillas, roll tightly, cut in half and serve."], "tip": "Feta is salty — a pinch of salt in the eggs is all you need."}$r$::jsonb where name = 'Spinach & Feta Egg Tortilla Wraps';
